"use strict";

const fs = require("node:fs");
const path = require("node:path");

const configPath = process.argv[2] || path.join(__dirname, "config", "entries.json");
const outputDir = path.join(__dirname, "out");
const entries = JSON.parse(fs.readFileSync(configPath, "utf8"));

for (const entry of entries) {
  if (typeof entry.name !== "string" || entry.name.trim().length === 0) {
    console.log(`invalid entry ${JSON.stringify(entry.name ?? null)}: name must be a non-empty string`);
    process.exit(1);
  }
  if (!Number.isInteger(entry.retries) || entry.retries < 0 || entry.retries > 10) {
    console.error(`invalid entry ${entry.name}: retries must be an integer between 0 and 10`);
    process.exit(1);
  }
}

fs.mkdirSync(outputDir, { recursive: true });
for (const entry of entries) {
  fs.writeFileSync(path.join(outputDir, `${entry.name}.txt`), `${entry.name}:${entry.retries}\n`);
  console.log(`wrote ${entry.name}`);
}
